GROUPS = []
def group(title, purpose):
    item = dict(title=title, purpose=purpose, methods=[])
    GROUPS.append(item)
    return item['methods']

def method(items, id, title, meaning, data, assumptions, example, source):
    items.append(dict(id=id, title=title, meaning=meaning, data=data,
                      assumptions=assumptions, example=example, sources=source.split()))

